import math
from climate_grid.scenario import aggregate_attribute_layers, compare_layer_scenarios

def layer_result():
    scenarios = ["ssp1", "ssp2", "ssp3"]
    elements = ["tas"]
    drivers = ["co2", "pop"]
    layers = [
        {"period": "2020-2039", "region": "north"},
        {"period": "2040-2059", "region": "north"},
    ]
    diffs = {
        (0, "ssp1"): (1.0, 0.3), (0, "ssp2"): (2.0, 0.4), (0, "ssp3"): (None, None),
        (1, "ssp1"): (1.5, 0.4), (1, "ssp2"): (None, None), (1, "ssp3"): (4.0, 0.5),
    }
    data = []
    for li, _ in enumerate(layers):
        for s in scenarios:
            for e in elements:
                for d in drivers:
                    diff, unc = diffs[(li, s)]
                    data.append({"scenario": s, "element": e, "driver": d,
                                 "difference": diff, "uncertainty": unc})
    return {
        "schema": "climate-grid/ra-layer-v1",
        "reference": {"period": "2000-2019", "region": "north"},
        "layers": layers,
        "scenarios": scenarios,
        "elements": elements,
        "drivers": drivers,
        "data": data,
    }

summary = aggregate_attribute_layers(layer_result())
for r in summary["data"]:
    print(r)
out = compare_layer_scenarios(summary)
for r in out["data"]:
    print(r)
